
export class Sound {
    url: string;
    volume: number;
    muted: boolean;
    sound: HTMLAudioElement;

    constructor(url: string, volume: number, muted: boolean){
        this.url = url;
        this.volume = volume;
        this.muted = muted;
    }

    play() {
    // if (this.sound) {
    //   this.sound.play()
    // } else {
        this.sound = new Audio(this.url);
        this.sound.volume = this.volume;
        this.sound.play();
    // }
    }
    toggleMute(){
        if(this.sound){
            this.muted ? this.unmute() : this.mute();
        }
    }

    unmute(){
        if(this.sound){
            this.muted = false; 
            this.sound.volume = this.volume;
        }
    }

    mute(){
        if(this.sound){
            this.muted = true;
            this.sound.volume = 0;
        }
    }

    pause(){
        if(this.sound){
            this.sound.pause();
        } 
    }
    unPause(){
        if (this.sound) {
            this.sound.play();
        }
    }
}
