import { UIElement } from "../../UI_Element";
import { Transform } from "../../transform";
import { Scene, SceneObject } from "./Scene";
import { type LevelDesigner } from "../levelDesigner"; 
import { LineSprite } from "../../line_sprite";

// wait times

export class Time {
    parentScene: Scene;
    waitTime: number;
    type: string;
    timeFactor: number;
    time: number;
    startingValues: {
        time: number;
        waitTime: number;
        timeFactor: number;
    };
    constructor(parentScene: Scene, waitTime: number) {
        this.type = "Time";
        this.parentScene = parentScene;
        this.waitTime = waitTime;
        this.timeFactor = 1;
        this.time = 0;
        this.startingValues = {
            time: 0,
            waitTime: waitTime,
            timeFactor: 1,
        };
    }

    // I'll have to make sure pausing doesn't fuck this up
    update(dT: number) {
        // maybe I just check if it's paused?
        this.time += dT;
        if(this.time >= this.waitTime * this.timeFactor) {
            this.endOperation();
        }
    }

    applyNewTimeFactor(factor: number) {
        this.timeFactor *= factor;
    }

    resetToStartingValues() {
        this.time = this.startingValues.time;
        this.waitTime = this.startingValues.waitTime;
        this.timeFactor = this.startingValues.timeFactor;
    }

    endOperationReset() {
        this.time = this.startingValues.time;
        this.waitTime = this.startingValues.waitTime;
        // keep time factor
    }

    endOperation() {
        this.endOperationReset();
        
        // this will have to be the scene it's in I think
        this.parentScene.nextElement();
    }

}

export type TimeSerialized = {
    type: "Time";
    waitTime: number;
}

// UIElement
export class TimeObject extends UIElement {
    UILineSprite: TimeObjectSprite;
    draggingLineSprite: TimeObjectSprite;
    waitTime: number;
    constructor(levelDesigner: LevelDesigner, waitTime: number, position: [number, number], parentScene: SceneObject) {
        super(levelDesigner, position, parentScene);
        this.waitTime = waitTime;
        this.widthHeight = [50, 40];
        this.clickRadius = 20;
        this.addMouseClickListener();
        this.addUIElementSprite(new TimeObjectSprite(this.transform, this.waitTime, this.widthHeight));
    }

    onMouseDoubleClick() {}

    unSelected() {
        this.UILineSprite.selected = false;
    }

    copy() {
        // this stuff is wrong anyway
        // return this.levelDesigner.addToClipBoard(new TimeObject(this.levelDesigner, this.serialize()));
    }

    copyLineSpriteForDragging() {
        const draggingSpriteTransform = new Transform(null, [this.transform.pos[0], this.transform.pos[1]]);
        return new TimeObjectSprite(draggingSpriteTransform, this.waitTime, this.widthHeight);
    }
    serialize(): TimeSerialized {
        return {
            type: "Time",
            waitTime: this.waitTime,
        };
    }

    changeTime(newTime: number) {
        this.waitTime = newTime;
        this.UILineSprite.waitTime = newTime;
    
    }
    onMouseClick() {
        this.levelDesigner.timeSelected(this);
        this.UILineSprite.selected = true;
    }
}


export class TimeObjectSprite extends LineSprite {
    waitTime: number;
    widthHeight: [number, number];
    selected: boolean;

    constructor(transform: Transform, waitTime: number, widthHeight: [number, number]) {
        super(transform);
        this.waitTime = waitTime;
        this.widthHeight = widthHeight;
        this.selected = false;
    }

    draw(ctx: CanvasRenderingContext2D) {
        const pos = this.transform.pos;
        ctx.save();
        ctx.translate(pos[0], pos[1]);

        this.drawFunction(ctx);
        ctx.restore();
    }

    drawFunction(ctx: CanvasRenderingContext2D) {
        const h = this.widthHeight[1];
        const w = this.widthHeight[0];
        
        ctx.fillStyle = "#A020F0";
        if(this.selected) ctx.fillStyle = "#419ef0";
        ctx.fillRect(0, 0, w, h);
        ctx.fillStyle = "rgba(0, 0, 0, 1)";
        ctx.font = "10px Arial";
        ctx.fillText(this.waitTime.toString(), 2, h/2);
    }
}